import sys

def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    codes = data[1:1 + n]
    total = 0
    for p in range(5):
        counts: dict[bytes, int] = {}
        for c in codes:
            key = c[:p] + c[p + 1:]
            counts[key] = counts.get(key, 0) + 1
        for k in counts.values():
            total += k * (k - 1) // 2
    same: dict[bytes, int] = {}
    for c in codes:
        same[c] = same.get(c, 0) + 1
    for k in same.values():
        total -= 5 * (k * (k - 1) // 2)
    print(total)

main()

