import sys
from collections import Counter

data = sys.stdin.read().split()
n = int(data[0])
count = Counter(data[1:1 + n])
letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
total = 0
for code, k in count.items():
    for p in range(5):
        for ch in letters:
            if ch != code[p]:
                total += k * count.get(code[:p] + ch + code[p + 1:], 0)
print(total // 2)
